 for lane in (-1,-2):
  lanes+=('<lane id="%d" type="driving" level="false"><link/><width sOffset="0" a="%s" b="0" c="0" d="0"/><roadMark sOffset="0" type="broken" weight="standard" color="white" width="0.12" laneChange="both"/></lane>'%(lane,width))
